def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 == r2 or abs(r2 - r1) != abs(c2 - c1):
                continue
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1

            # Draw the 1 diagonal segment between the two markers.
            segment = []
            r, c = r1, c1
            while True:
                segment.append((r, c))
                if out[r][c] == background:
                    out[r][c] = 1
                if (r, c) == (r2, c2):
                    break
                r += dr
                c += dc

            # A 6 on this diagonal generates the perpendicular 6 diagonal.
            for sr, sc in sixes:
                if (sr, sc) not in segment:
                    continue
                pdr, pdc = 1, -1 if dr == dc else 1
                r, c = sr, sc
                while 0 <= r - pdr < h and 0 <= c - pdc < w:
                    r -= pdr
                    c -= pdc
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] == background:
                        out[r][c] = 6
                    r += pdr
                    c += pdc
    return out
